233: export async function claudeCliPath() {
234:     if (process.env.CLAUDE_CODE_EXECUTABLE) {
235:         return process.env.CLAUDE_CODE_EXECUTABLE;
236:     }
237:     // The SDK's CLI is a native binary shipped as a platform-specific optional
238:     // dependency of @anthropic-ai/claude-agent-sdk. Resolve via a require bound
239:     // to the SDK so nested installs are found even when npm doesn't hoist.
240:     const { createRequire } = await import("node:module");
241:     const req = createRequire(import.meta.resolve("@anthropic-ai/claude-agent-sdk"));
242:     const ext = process.platform === "win32" ? ".exe" : "";
243:     // On linux, both glibc and musl variants may be installed side-by-side
244:     // (e.g. bunx hydrates every optional dep), so picking one by trial is
245:     // unreliable: the wrong binary segfaults at runtime instead of failing to
246:     // spawn. Detect the runtime libc and prefer the matching variant, falling
247:     // back to the other only if the preferred one isn't installed.
248:     const candidates = process.platform === "linux"
249:         ? isMuslLibc()
250:             ? [
251:                 `@anthropic-ai/claude-agent-sdk-linux-${process.arch}-musl/claude${ext}`,
252:                 `@anthropic-ai/claude-agent-sdk-linux-${process.arch}/claude${ext}`,
253:             ]
254:             : [
255:                 `@anthropic-ai/claude-agent-sdk-linux-${process.arch}/claude${ext}`,
256:                 `@anthropic-ai/claude-agent-sdk-linux-${process.arch}-musl/claude${ext}`,
257:             ]
258:         : [`@anthropic-ai/claude-agent-sdk-${process.platform}-${process.arch}/claude${ext}`];
259:     for (const candidate of candidates) {
260:         try {
261:             return req.resolve(candidate);
262:         }
263:         catch {
264:             // try next candidate
265:         }
266:     }
267:     throw new Error(`Claude native binary not found for ${process.platform}-${process.arch}. ` +
268:         `Reinstall @anthropic-ai/claude-agent-sdk without --omit=optional, or set CLAUDE_CODE_EXECUTABLE.`);

